import { useCallback, useEffect, useState } from "react";
import { ChevronDown, ChevronRight, File, Folder, FolderOpen, GitBranch, Image as ImageIcon, RefreshCw } from "lucide-react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
// @ts-ignore wailsjs bindings are generated by wails build
import { ListDirectory, ReadDocument, ReadImage, SaveDocument } from "../../../wailsjs/go/controllers/Files";
// @ts-ignore wailsjs bindings are generated by wails build
import {
  GetSourceControlStatus,
  ReadSourceControlDiff,
  ShowSourceControlFile,
  StartSourceControlCommit,
  StartSourceControlPush,
  StartSourceControlStage,
  StartSourceControlUnstage,
} from "../../../wailsjs/go/controllers/Git";
import DocumentEditor, { ConflictDiff } from "../documents/DocumentEditor";
import { fileLanguage } from "../../lib/fileLanguage";
import { useT } from "../../lib/i18n";

type Entry = { name: string; isDir: boolean; size?: number; blocked?: boolean; blockReason?: string };
type Doc = { content: string; revision: string; readOnly: boolean; bom: boolean; eol: string; encoding: string };

// Image extensions we can preview.
const IMAGE_EXT = /\.(png|jpe?g|gif|webp)$/i;
const MARKDOWN_EXT = /\.(md|markdown)$/i;

export default function WorkspaceNavigator({ projectName }: { projectName: string }) {
  const t = useT();
  const [tab, setTab] = useState<"files" | "git">("files");
  const [dirtyCount, setDirtyCount] = useState(0);

  // Report dirty state to the window so the shell can warn on close.
  useEffect(() => {
    (window as any).__kitodock_dirtyDocs = dirtyCount;
  }, [dirtyCount]);

  return (
    <div className="flex h-full flex-col">
      <div className="flex border-b border-white/10 px-1 text-xs">
        <button
          type="button"
          onClick={() => setTab("files")}
          className={`px-3 py-1.5 ${tab === "files" ? "border-b-2 border-accent text-white" : "text-white/50 hover:text-white/80"}`}
        >
          {t("workspace.files")}
        </button>
        <button
          type="button"
          onClick={() => setTab("git")}
          className={`px-3 py-1.5 ${tab === "git" ? "border-b-2 border-accent text-white" : "text-white/50 hover:text-white/80"}`}
        >
          {t("workspace.git")}
        </button>
      </div>
      {tab === "files" ? <FilesTab projectName={projectName} onDirtyChange={setDirtyCount} /> : <GitTab projectName={projectName} />}
    </div>
  );
}

// --- Files Tab with recursive tree + editor/preview -----------------------------

function FilesTab({ projectName, onDirtyChange }: { projectName: string; onDirtyChange: (count: number) => void }) {
  const t = useT();
  const [doc, setDoc] = useState<Doc | null>(null);
  const [docPath, setDocPath] = useState("");
  const [dirty, setDirty] = useState(false);
  const [conflict, setConflict] = useState<{ original: string; mine: string } | null>(null);
  const [previewMode, setPreviewMode] = useState(true);

  // Report dirty state upward.
  useEffect(() => {
    onDirtyChange(dirty ? 1 : 0);
  }, [dirty, onDirtyChange]);

  const openDoc = useCallback(async (filePath: string) => {
    try {
      const result = await ReadDocument("project", projectName, filePath);
      const d = result as any;
      setDoc({ content: d?.content ?? "", revision: d?.revision ?? "", readOnly: !!d?.readOnly, bom: d?.bom, eol: d?.eol, encoding: d?.encoding ?? "utf-8" });
      setDocPath(filePath);
      setDirty(false);
      setConflict(null);
      setPreviewMode(true);
    } catch { /* not found */ }
  }, [projectName]);

  const save = useCallback(async (force?: boolean) => {
    if (!doc || !docPath || doc.readOnly || !dirty) return;
    try {
      const [result, newRev] = await SaveDocument("project", projectName, docPath, doc.content, force ? "" : doc.revision);
      if (result === "ok") {
        setDoc((d) => (d ? { ...d, revision: newRev } : d));
        setDirty(false);
        setConflict(null);
      } else if (result === "conflict") {
        const fresh = await ReadDocument("project", projectName, docPath);
        setConflict({ original: (fresh as any)?.content ?? "", mine: doc.content });
      }
    } catch { /* failed */ }
  }, [doc, docPath, projectName, dirty]);

  // Ctrl+S
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === "s" && docPath) {
        e.preventDefault();
        void save();
      }
    };
    window.addEventListener("keydown", onKey, true);
    return () => window.removeEventListener("keydown", onKey, true);
  }, [save, docPath]);

  const isMarkdown = MARKDOWN_EXT.test(docPath);
  const isImage = IMAGE_EXT.test(docPath);

  return (
    <div className="flex min-h-0 flex-1">
      <FileTree projectName={projectName} onOpen={openDoc} activePath={docPath} />
      <div className="relative min-w-0 flex-1">
        {doc ? (
          <>
            <div className="flex items-center justify-between border-b border-white/10 px-3 py-1 text-xs">
              <span className="truncate font-mono text-white/70">{docPath}</span>
              <div className="flex items-center gap-2">
                {doc.readOnly && <span className="text-amber-300/70">{t("workspace.readOnly")}</span>}
                {dirty && <span className="text-accent2">●</span>}
                {isMarkdown && (
                  <button
                    type="button"
                    onClick={() => setPreviewMode(!previewMode)}
                    className="rounded border border-white/10 px-1.5 py-0.5 text-white/50 hover:bg-white/10"
                  >
                    {previewMode ? "Source" : "Preview"}
                  </button>
                )}
                {conflict && (
                  <button
                    type="button"
                    onClick={() => void save(true)}
                    className="rounded border border-amber-400/40 bg-amber-400/10 px-1.5 py-0.5 text-amber-300 hover:bg-amber-400/20"
                  >
                    {t("workspace.saveMerged")}
                  </button>
                )}
                <button
                  type="button"
                  onClick={() => void save()}
                  disabled={!dirty || doc.readOnly}
                  className="rounded border border-white/10 px-2 py-0.5 text-white/70 hover:bg-white/10 disabled:opacity-40"
                >
                  {t("workspace.save")}
                </button>
              </div>
            </div>
            <div className="h-[calc(100%-28px)]">
              {isImage ? (
                <ImagePreview projectName={projectName} path={docPath} />
              ) : conflict ? (
                <ConflictDiff original={conflict.original} modified={conflict.mine} language={fileLanguage(docPath)} />
              ) : isMarkdown && previewMode ? (
                <MarkdownPreview content={doc.content} />
              ) : (
                <DocumentEditor
                  value={doc.content}
                  language={fileLanguage(docPath)}
                  readOnly={doc.readOnly}
                  onChange={(v) => {
                    setDoc((d) => (d ? { ...d, content: v } : d));
                    setDirty(true);
                  }}
                />
              )}
            </div>
          </>
        ) : (
          <div className="flex h-full items-center justify-center text-xs text-white/30">
            {t("workspace.selectFile")}
          </div>
        )}
      </div>
    </div>
  );
}

// --- Recursive File Tree ---------------------------------------------------------

function FileTree({ projectName, onOpen, activePath }: { projectName: string; onOpen: (path: string) => void; activePath: string }) {
  const [entries, setEntries] = useState<Entry[]>([]);
  const [expanded, setExpanded] = useState<Map<string, Entry[]>>(new Map());
  const [loading, setLoading] = useState(false);

  const loadDir = useCallback(async (dirPath: string): Promise<Entry[]> => {
    try {
      const result = await ListDirectory("project", projectName, dirPath, "");
      return (result as any)?.entries ?? [];
    } catch {
      return [];
    }
  }, [projectName]);

  useEffect(() => {
    const timer = setTimeout(async () => {
      setLoading(true);
      const root = await loadDir("");
      setEntries(root);
      setLoading(false);
    }, 0);
    return () => clearTimeout(timer);
  }, [loadDir]);

  const toggle = async (dirPath: string) => {
    if (expanded.has(dirPath)) {
      setExpanded((prev) => { const next = new Map(prev); next.delete(dirPath); return next; });
    } else {
      const children = await loadDir(dirPath);
      setExpanded((prev) => new Map(prev).set(dirPath, children));
    }
  };

  const renderEntries = (list: Entry[], parentPath: string, depth: number): React.ReactNode[] => {
    return list.map((entry) => {
      const childPath = parentPath ? `${parentPath}/${entry.name}` : entry.name;
      const isOpen = expanded.has(childPath);
      return (
        <div key={childPath}>
          <button
            type="button"
            disabled={entry.blocked}
            onClick={() => {
              if (entry.isDir) void toggle(childPath);
              else onOpen(childPath);
            }}
            className={`flex w-full items-center gap-1 rounded px-2 py-0.5 text-left text-xs ${
              entry.blocked ? "text-white/20" : "text-white/70 hover:bg-white/5"
            } ${activePath === childPath ? "bg-white/10 text-white" : ""}`}
            style={{ paddingLeft: `${8 + depth * 12}px` }}
          >
            {entry.isDir ? (
              <>
                {isOpen ? <ChevronDown className="h-3 w-3 text-white/40" /> : <ChevronRight className="h-3 w-3 text-white/40" />}
                {isOpen ? <FolderOpen className="h-3.5 w-3.5 text-accent2" /> : <Folder className="h-3.5 w-3.5 text-accent2" />}
              </>
            ) : (
              <span className="w-3" />
            )}
            {entry.isDir ? null : <File className="h-3.5 w-3.5 text-white/40" />}
            <span className="truncate">{entry.name}</span>
            {entry.blocked && <span className="text-[9px] text-red-300/50">({entry.blockReason})</span>}
          </button>
          {entry.isDir && isOpen && expanded.get(childPath) && (
            <div>{renderEntries(expanded.get(childPath)!, childPath, depth + 1)}</div>
          )}
        </div>
      );
    });
  };

  return (
    <div className="w-full overflow-y-auto border-r border-white/10 p-1" style={{ maxWidth: "280px" }}>
      {loading && <p className="px-2 py-1 text-xs text-white/40">…</p>}
      {renderEntries(entries, "", 0)}
    </div>
  );
}

// --- Markdown Preview ---------------------------------------------------------------

function MarkdownPreview({ content }: { content: string }) {
  return (
    <div className="h-full overflow-y-auto p-4">
      <div className="prose prose-invert prose-sm max-w-none text-white/80">
        <ReactMarkdown remarkPlugins={[remarkGfm]}>{content}</ReactMarkdown>
      </div>
    </div>
  );
}

// --- Image Preview -------------------------------------------------------------------

function ImagePreview({ projectName, path }: { projectName: string; path: string }) {
  const [data, setData] = useState<string>("");
  const [mime, setMime] = useState<string>("");
  const [error, setError] = useState("");

  useEffect(() => {
    const timer = setTimeout(async () => {
      try {
        const result = await ReadImage("project", projectName, path);
        const img = result as any;
        if (img?.data) {
          setData(img.data);
          setMime(img.mime ?? "image/png");
        } else {
          setError("Cannot display image");
        }
      } catch {
        setError("Cannot display image");
      }
    }, 0);
    return () => clearTimeout(timer);
  }, [projectName, path]);

  if (error) return <div className="flex h-full items-center justify-center text-xs text-white/30">{error}</div>;
  if (!data) return <div className="flex h-full items-center justify-center text-xs text-white/30">…</div>;
  return (
    <div className="flex h-full items-center justify-center p-4">
      <img src={`data:${mime};base64,${data}`} alt={path} className="max-h-full max-w-full object-contain" />
    </div>
  );
}

// --- Git Tab ------------------------------------------------------------------------

type GitFile = { path: string; staged: boolean; unstaged: boolean; untracked: boolean };
type GitStatus = { branch: string; upstream?: string; ahead: number; behind: number; files: GitFile[] };

function GitTab({ projectName }: { projectName: string }) {
  const t = useT();
  const [status, setStatus] = useState<GitStatus | null>(null);
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const [diffFile, setDiffFile] = useState<string | null>(null);
  const [diffContent, setDiffContent] = useState<{ original: string; modified: string } | null>(null);

  const refresh = useCallback(async () => {
    try {
      const s = await GetSourceControlStatus(projectName);
      setStatus(s as any);
    } catch { /* not a repo */ }
  }, [projectName]);

  useEffect(() => {
    const timer = setTimeout(() => void refresh(), 0);
    return () => clearTimeout(timer);
  }, [refresh]);

  const showDiff = useCallback(async (path: string) => {
    if (diffFile === path) {
      setDiffFile(null);
      setDiffContent(null);
      return;
    }
    setDiffFile(path);
    try {
      const [headContent, diffText] = await Promise.all([
        ShowSourceControlFile(projectName, path),
        ReadSourceControlDiff(projectName, path),
      ]);
      // For new files, original is empty. For modified, use HEAD content.
      setDiffContent({ original: headContent ?? "", modified: diffText ? "" : "" });
      // Actually, let's use the diff text to show in a simpler way.
      // For now, show HEAD vs what's on disk by reading the file.
      const diskDoc = await ReadDocument("project", projectName, path);
      setDiffContent({ original: headContent ?? "", modified: (diskDoc as any)?.content ?? "" });
    } catch {
      setDiffContent(null);
    }
  }, [projectName, diffFile]);

  const stage = async (paths: string[]) => {
    setBusy(true);
    await StartSourceControlStage(projectName, paths);
    setBusy(false);
    void refresh();
  };

  const unstage = async (paths: string[]) => {
    setBusy(true);
    await StartSourceControlUnstage(projectName, paths);
    setBusy(false);
    void refresh();
  };

  const commit = async () => {
    if (!message.trim()) return;
    setBusy(true);
    await StartSourceControlCommit(projectName, message);
    setMessage("");
    setBusy(false);
    void refresh();
  };

  const push = async () => {
    setBusy(true);
    await StartSourceControlPush(projectName);
    setBusy(false);
    void refresh();
  };

  if (!status) {
    return <div className="flex h-full items-center justify-center text-xs text-white/30">{t("workspace.git.notRepo")}</div>;
  }

  const staged = status.files.filter((f) => f.staged);
  const unstaged = status.files.filter((f) => !f.staged);

  return (
    <div className="flex h-full flex-col">
      {/* Diff viewer (when a file is clicked) */}
      {diffFile && diffContent && (
        <div className="h-[40%] border-b border-white/10">
          <div className="flex items-center justify-between px-2 py-1 text-xs">
            <span className="truncate font-mono text-white/70">{diffFile}</span>
            <button type="button" onClick={() => { setDiffFile(null); setDiffContent(null); }} className="text-white/40 hover:text-white">✕</button>
          </div>
          <div className="h-[calc(100%-24px)]">
            <ConflictDiff original={diffContent.original} modified={diffContent.modified} language={fileLanguage(diffFile)} />
          </div>
        </div>
      )}

      <div className="flex min-h-0 flex-1 flex-col gap-2 overflow-y-auto p-2 text-xs">
        <div className="flex items-center gap-2 border-b border-white/10 pb-2">
          <GitBranch className="h-3.5 w-3.5 text-accent2" />
          <span className="font-mono text-white/80">{status.branch}</span>
          {status.upstream && (
            <span className="text-white/40">
              {status.ahead > 0 && `↑${status.ahead}`}
              {status.behind > 0 && ` ↓${status.behind}`}
              {" "}{status.upstream}
            </span>
          )}
        </div>

        {/* Staged */}
        <div>
          <div className="mb-1 flex items-center justify-between">
            <span className="font-medium text-white/60">{t("workspace.git.staged")} ({staged.length})</span>
            {staged.length > 0 && (
              <button type="button" onClick={() => void unstage(staged.map((f) => f.path))} className="text-white/40 hover:text-white">
                {t("workspace.git.unstageAll")}
              </button>
            )}
          </div>
          {staged.map((f) => (
            <button
              key={f.path}
              type="button"
              onClick={() => void showDiff(f.path)}
              className={`flex w-full items-center gap-1 rounded px-1 py-0.5 text-left hover:bg-white/5 ${diffFile === f.path ? "bg-white/10" : ""}`}
            >
              <span className="min-w-4 text-center text-emerald-400">+</span>
              <span className="flex-1 truncate text-white/70">{f.path}</span>
              <span role="button" tabIndex={-1} onClick={(e) => { e.stopPropagation(); void unstage([f.path]); }} className="text-white/30 hover:text-white">−</span>
            </button>
          ))}
        </div>

        {/* Unstaged */}
        <div>
          <div className="mb-1 flex items-center justify-between">
            <span className="font-medium text-white/60">{t("workspace.git.changes")} ({unstaged.length})</span>
            {unstaged.length > 0 && (
              <button type="button" onClick={() => void stage(unstaged.map((f) => f.path))} className="text-white/40 hover:text-white">
                {t("workspace.git.stageAll")}
              </button>
            )}
          </div>
          {unstaged.map((f) => (
            <button
              key={f.path}
              type="button"
              onClick={() => void showDiff(f.path)}
              className={`flex w-full items-center gap-1 rounded px-1 py-0.5 text-left hover:bg-white/5 ${diffFile === f.path ? "bg-white/10" : ""}`}
            >
              <span className={`min-w-4 text-center ${f.untracked ? "text-red-400" : "text-amber-400"}`}>
                {f.untracked ? "?" : "M"}
              </span>
              <span className="flex-1 truncate text-white/70">{f.path}</span>
              <span role="button" tabIndex={-1} onClick={(e) => { e.stopPropagation(); void stage([f.path]); }} className="text-white/30 hover:text-white">+</span>
            </button>
          ))}
        </div>

        {/* Commit + Push */}
        <div className="mt-auto space-y-2 border-t border-white/10 pt-2">
          <textarea
            className="input w-full resize-none text-xs"
            rows={2}
            placeholder={t("workspace.git.commitMessage")}
            value={message}
            onChange={(e) => setMessage(e.target.value)}
          />
          <div className="flex gap-2">
            <button
              type="button"
              onClick={() => void commit()}
              disabled={!message.trim() || staged.length === 0 || busy}
              className="flex-1 rounded bg-accent px-3 py-1.5 text-xs font-medium text-white disabled:opacity-40"
            >
              {t("workspace.git.commit")}
            </button>
            <button
              type="button"
              onClick={() => void push()}
              disabled={busy}
              className="flex-1 rounded border border-white/15 bg-white/5 px-3 py-1.5 text-xs text-white/70 hover:bg-white/10 disabled:opacity-40"
            >
              {t("workspace.git.push")}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
